const endpoints=['http://jenkins.riseup.co.il/','https://jenkins.riseup.co.il/','http://52.16.40.9/','https://52.16.40.9/','http://jenkins.riseup.co.il:8080/','http://bastion.riseup.co.il/','https://bastion.riseup.co.il/'];
console.log('LAB_IP',await fetch('https://api.ipify.org').then(r=>r.text()));
for(const url of endpoints){try{const r=await fetch(url,{redirect:'manual',signal:AbortSignal.timeout(12000),headers:{'user-agent':'Mozilla/5.0'}});const b=await r.text();console.log('DEV',JSON.stringify({url,status:r.status,headers:Object.fromEntries(r.headers),body:b.slice(0,2000)}));}catch(e){console.log('DEVERR',url,String(e))}}
